const raw = $json.choices[0].message.content;
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { category: 'unknown', summary: 'Model response could not be read, needs manual review' }; }
const email = $('Settings').item.json;
return [{ json: { category: parsed.category, summary: parsed.summary || '', subject: email.subject || '', from: (email.from && email.from.value && email.from.value[0] && email.from.value[0].address) || '', id: email.id, threadId: email.threadId, receivedAt: new Date().toISOString() } }];
